//! Run the frozen conformance vectors against this Rust core.
//!
//! This is what `abb vectors check` executes and what `R-PRO-01` and
//! `R-TST-01` require before any production receipt is emitted. The vectors
//! were generated by the Python reference in `vectors/tools/`; agreement here
//! is the cross-language check of `PROTOCOL.md` section 17.
//!
//! Every case is checked in both directions where that is meaningful: a proof
//! is rebuilt *and* verified, a canonical form is produced *and* re-parsed, a
//! signature is verified rather than re-signed.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use abb_checkpoint::{
    check_extends, tagged_bytes, tags, CheckpointPayload, KeyManifest, Role, ZERO_HASH_HEX,
};
use abb_jcs::{hex_decode, hex_lower, Limits, Value};
use abb_merkle as merkle;

use crate::b64;

/// The result of running one vector file.
#[derive(Debug, Clone)]
pub struct SetOutcome {
    /// Path relative to the vectors directory.
    pub file: String,
    /// Cases that passed.
    pub passed: usize,
    /// One message per failing case, naming the case id.
    pub failures: Vec<String>,
}

impl SetOutcome {
    fn new(file: &str) -> Self {
        Self {
            file: file.to_owned(),
            passed: 0,
            failures: Vec::new(),
        }
    }

    fn record(&mut self, case_id: &str, outcome: Result<(), String>) {
        match outcome {
            Ok(()) => self.passed += 1,
            Err(message) => self.failures.push(format!("{case_id}: {message}")),
        }
    }
}

/// Everything that can stop the runner before it reaches a single case.
#[derive(Debug)]
pub enum RunnerError {
    /// A vector file is missing or unreadable.
    Unreadable(String),
    /// A vector file is not the shape the runner expects.
    Malformed(String),
}

impl std::fmt::Display for RunnerError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Unreadable(m) => write!(f, "cannot read {m}"),
            Self::Malformed(m) => write!(f, "malformed vector file: {m}"),
        }
    }
}

type Outcome = Result<(), String>;

/// A set runner: it reads one vector file's parsed document and reports results.
type SetRunner = fn(&Value, &str) -> Result<SetOutcome, RunnerError>;

// --------------------------------------------------------------------------- //
// small helpers over abb_jcs::Value
// --------------------------------------------------------------------------- //

fn load(path: &Path) -> Result<Value, RunnerError> {
    let bytes =
        fs::read(path).map_err(|e| RunnerError::Unreadable(format!("{}: {e}", path.display())))?;
    // Relaxed limits: a vector file is a repository file, not a protocol
    // document, and is allowed to be larger than one event.
    abb_jcs::parse_bytes(&bytes, &Limits::relaxed())
        .map_err(|e| RunnerError::Malformed(format!("{}: {e}", path.display())))
}

fn cases(doc: &Value, file: &str) -> Result<Vec<Value>, RunnerError> {
    doc.get("cases")
        .and_then(Value::as_array)
        .map(<[Value]>::to_vec)
        .ok_or_else(|| RunnerError::Malformed(format!("{file}: no cases array")))
}

fn case_id(case: &Value) -> String {
    case.get("id")
        .and_then(Value::as_str)
        .unwrap_or("<no id>")
        .to_owned()
}

fn need_str(node: &Value, path: &str) -> Result<String, String> {
    node.get(path)
        .and_then(Value::as_str)
        .map(str::to_owned)
        .ok_or_else(|| format!("missing string field {path}"))
}

fn need_int(node: &Value, path: &str) -> Result<i64, String> {
    node.get(path)
        .and_then(Value::as_int)
        .ok_or_else(|| format!("missing integer field {path}"))
}

fn need_obj<'a>(node: &'a Value, path: &str) -> Result<&'a Value, String> {
    node.get(path)
        .ok_or_else(|| format!("missing object field {path}"))
}

fn need_hash(node: &Value, path: &str) -> Result<[u8; 32], String> {
    let text = need_str(node, path)?;
    hash_from_hex(&text).map_err(|e| format!("{path}: {e}"))
}

fn hash_from_hex(text: &str) -> Result<[u8; 32], String> {
    if text.len() != 64 {
        return Err("NOT_HEX (wrong length)".to_owned());
    }
    let raw = hex_decode(text).map_err(|_| "NOT_HEX".to_owned())?;
    raw.try_into()
        .map_err(|_| "NOT_HEX (wrong length)".to_owned())
}

fn need_path(node: &Value, field: &str) -> Result<Vec<[u8; 32]>, String> {
    let items = node
        .get(field)
        .and_then(Value::as_array)
        .ok_or_else(|| format!("missing array field {field}"))?;
    items
        .iter()
        .map(|item| {
            let text = item
                .as_str()
                .ok_or_else(|| "path element is not a string".to_owned())?;
            hash_from_hex(text)
        })
        .collect()
}

fn need_bytes_b64(node: &Value, field: &str) -> Result<Vec<u8>, String> {
    let text = need_str(node, field)?;
    b64::decode(&text).map_err(|e| format!("{field}: {e}"))
}

fn expect_block(case: &Value) -> Result<&Value, String> {
    need_obj(case, "expect")
}

// --------------------------------------------------------------------------- //
// the sets
// --------------------------------------------------------------------------- //

fn check_jcs_canonical(doc: &Value, file: &str) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        out.record(&id, run_jcs_canonical(&case));
    }
    Ok(out)
}

fn run_jcs_canonical(case: &Value) -> Outcome {
    let input = case
        .get("input")
        .ok_or_else(|| "missing input".to_owned())?;
    let expect = expect_block(case)?;
    let want = need_str(expect, "canonical")?;

    let got = abb_jcs::to_canonical(input).map_err(|e| format!("serialization failed: {e}"))?;
    if got != want {
        return Err(format!("canonical mismatch\n  want: {want}\n  got:  {got}"));
    }
    // The declared digest must be the digest of these exact bytes.
    let want_digest = need_str(expect, "canonical_sha256")?;
    let got_digest = abb_jcs::canonical_sha256_hex(input).map_err(|e| e.to_string())?;
    if got_digest != want_digest {
        return Err(format!(
            "digest mismatch: want {want_digest}, got {got_digest}"
        ));
    }
    // And the canonical text must be a fixed point.
    if !abb_jcs::is_canonical(&got) {
        return Err("canonical output is not itself canonical".to_owned());
    }
    Ok(())
}

fn check_jcs_invalid(doc: &Value, file: &str) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        out.record(&id, run_jcs_invalid(&case));
    }
    Ok(out)
}

fn run_jcs_invalid(case: &Value) -> Outcome {
    let expect = expect_block(case)?;
    let want_reason = need_str(expect, "reason")?;
    let limits = Limits::protocol();

    let result = if let Some(text) = case.get("input_text").and_then(Value::as_str) {
        abb_jcs::parse_str(text, &limits)
    } else {
        // Raw bytes, for the cases that cannot be written as JSON text.
        let bytes = need_bytes_b64(case, "input_b64")?;
        abb_jcs::parse_bytes(&bytes, &limits)
    };

    match result {
        Ok(_) => Err(format!("accepted, expected rejection {want_reason}")),
        Err(err) => {
            if err.reason.as_str() == want_reason {
                Ok(())
            } else {
                Err(format!(
                    "rejected as {}, expected {want_reason}",
                    err.reason.as_str()
                ))
            }
        }
    }
}

fn check_hashing_tags(doc: &Value, file: &str) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    let mut digests: BTreeMap<String, String> = BTreeMap::new();
    for case in cases(doc, file)? {
        let id = case_id(&case);
        let outcome = (|| -> Outcome {
            let input = need_obj(&case, "input")?;
            let expect = expect_block(&case)?;
            let data = need_bytes_b64(input, "data_b64")?;
            let want = need_str(expect, "digest")?;
            let got = match input.get("tag") {
                Some(Value::Str(tag)) => {
                    // The tag must be one of the nine fixed tags.
                    if !tags::ALL.contains(&tag.as_str()) {
                        return Err(format!("unknown domain tag {tag}"));
                    }
                    hex_lower(&abb_checkpoint::tagged_digest(tag, &data))
                }
                // D-03: the artifact digest carries no tag.
                Some(Value::Null) | None => hex_lower(&abb_checkpoint::artifact_digest(&data)),
                Some(_) => return Err("tag must be a string or null".to_owned()),
            };
            if got != want {
                return Err(format!("digest mismatch: want {want}, got {got}"));
            }
            if let Some(previous) = digests.insert(got.clone(), id.clone()) {
                return Err(format!(
                    "domain separation broken: same digest as {previous}"
                ));
            }
            Ok(())
        })();
        out.record(&id, outcome);
    }
    Ok(out)
}

fn check_hashing_tree(doc: &Value, file: &str) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        let outcome = (|| -> Outcome {
            let input = need_obj(&case, "input")?;
            let expect = expect_block(&case)?;
            let want = need_str(expect, "digest")?;
            let kind = need_str(input, "kind")?;
            let got = match kind.as_str() {
                "empty_tree" => hex_lower(&merkle::empty_root()),
                "leaf" => hex_lower(&merkle::leaf_hash(&need_bytes_b64(input, "data_b64")?)),
                "node" => {
                    let left = need_hash(input, "left")?;
                    let right = need_hash(input, "right")?;
                    hex_lower(&merkle::node_hash(&left, &right))
                }
                other => return Err(format!("unknown kind {other}")),
            };
            if got != want {
                return Err(format!("digest mismatch: want {want}, got {got}"));
            }
            Ok(())
        })();
        out.record(&id, outcome);
    }
    Ok(out)
}

fn check_merkle_roots(doc: &Value, file: &str) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        let outcome = (|| -> Outcome {
            let input = need_obj(&case, "input")?;
            let expect = expect_block(&case)?;
            let count = usize::try_from(need_int(input, "leaf_count")?)
                .map_err(|_| "leaf_count out of range".to_owned())?;
            let want = need_str(expect, "root_hash")?;
            let leaves = merkle::synthetic_leaves(count);
            let recursive = hex_lower(&merkle::mth(&leaves));
            if recursive != want {
                return Err(format!("mth mismatch: want {want}, got {recursive}"));
            }
            // The frontier the signer keeps must agree with the definition.
            let frontier = merkle::Frontier::from_leaf_data(&leaves);
            if hex_lower(&frontier.root()) != want {
                return Err("frontier root differs from the recursive root".to_owned());
            }
            if frontier.size() != count as u64 {
                return Err("frontier size wrong".to_owned());
            }
            Ok(())
        })();
        out.record(&id, outcome);
    }
    Ok(out)
}

fn check_merkle_inclusion(doc: &Value, file: &str) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        let outcome = (|| -> Outcome {
            let input = need_obj(&case, "input")?;
            let expect = expect_block(&case)?;
            let size = usize::try_from(need_int(input, "tree_size")?)
                .map_err(|_| "tree_size out of range".to_owned())?;
            let index = usize::try_from(need_int(input, "leaf_index")?)
                .map_err(|_| "leaf_index out of range".to_owned())?;
            let leaves = merkle::synthetic_leaves(size);
            let leaf = leaves
                .get(index)
                .ok_or_else(|| "index past leaves".to_owned())?;

            let want_leaf = need_str(expect, "leaf_hash")?;
            if hex_lower(&merkle::leaf_hash(leaf)) != want_leaf {
                return Err("leaf hash mismatch".to_owned());
            }

            // Rebuild the path ...
            let built = merkle::inclusion_path(index, &leaves).map_err(|e| e.to_string())?;
            let want_path = need_path(expect, "path")?;
            if built != want_path {
                return Err(format!(
                    "audit path mismatch: {} elements built, {} expected",
                    built.len(),
                    want_path.len()
                ));
            }
            // ... and verify the frozen one independently.
            let derived = merkle::verify_inclusion(
                &merkle::leaf_hash(leaf),
                index as u64,
                size as u64,
                &want_path,
            )
            .map_err(|e| format!("verification failed: {e}"))?;
            let want_root = need_str(expect, "root_hash")?;
            if hex_lower(&derived) != want_root {
                return Err(format!(
                    "derived root {} != {want_root}",
                    hex_lower(&derived)
                ));
            }
            Ok(())
        })();
        out.record(&id, outcome);
    }
    Ok(out)
}

fn check_merkle_consistency(doc: &Value, file: &str) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        let outcome = (|| -> Outcome {
            let input = need_obj(&case, "input")?;
            let expect = expect_block(&case)?;
            let first = usize::try_from(need_int(input, "first_size")?)
                .map_err(|_| "first_size out of range".to_owned())?;
            let second = usize::try_from(need_int(input, "second_size")?)
                .map_err(|_| "second_size out of range".to_owned())?;
            let leaves = merkle::synthetic_leaves(second);
            let first_root = merkle::mth(&merkle::synthetic_leaves(first));
            if hex_lower(&first_root) != need_str(expect, "first_root")? {
                return Err("first root mismatch".to_owned());
            }
            let built = merkle::consistency_path(first, &leaves).map_err(|e| e.to_string())?;
            let want_path = need_path(expect, "path")?;
            if built != want_path {
                return Err(format!(
                    "consistency path mismatch: {} built, {} expected",
                    built.len(),
                    want_path.len()
                ));
            }
            let derived =
                merkle::verify_consistency(first as u64, second as u64, &first_root, &want_path)
                    .map_err(|e| format!("verification failed: {e}"))?;
            if hex_lower(&derived) != need_str(expect, "second_root")? {
                return Err("derived second root mismatch".to_owned());
            }
            Ok(())
        })();
        out.record(&id, outcome);
    }
    Ok(out)
}

fn check_merkle_malformed(doc: &Value, file: &str) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        let outcome = (|| -> Outcome {
            let input = need_obj(&case, "input")?;
            let expect = expect_block(&case)?;
            let want_reason = need_str(expect, "reason")?;
            let kind = need_str(input, "proof_kind")?;

            // A path element that is not hex must be refused before any
            // verification runs at all.
            let path = match need_path(input, "path") {
                Ok(path) => path,
                Err(message) => {
                    return if message.contains("NOT_HEX") && want_reason == "NOT_HEX" {
                        Ok(())
                    } else {
                        Err(format!(
                            "path parsing failed as {message}, expected {want_reason}"
                        ))
                    }
                }
            };

            let error = if kind == "inclusion" {
                let size = need_int(input, "tree_size")?;
                let index = need_int(input, "leaf_index")?;
                let leaves = merkle::synthetic_leaves(
                    usize::try_from(size.max(index + 1)).unwrap_or_default(),
                );
                let leaf = leaves
                    .get(usize::try_from(index).unwrap_or_default())
                    .ok_or_else(|| "index past leaves".to_owned())?;
                merkle::verify_inclusion(&merkle::leaf_hash(leaf), index as u64, size as u64, &path)
                    .err()
            } else {
                let first = need_int(input, "first_size")?;
                let second = need_int(input, "second_size")?;
                let first_root = need_hash(input, "first_root")?;
                merkle::verify_consistency(first as u64, second as u64, &first_root, &path).err()
            };

            match error {
                None => Err(format!("accepted, expected rejection {want_reason}")),
                Some(err) if err.as_str() == want_reason => Ok(()),
                Some(err) => Err(format!(
                    "rejected as {}, expected {want_reason}",
                    err.as_str()
                )),
            }
        })();
        out.record(&id, outcome);
    }
    Ok(out)
}

/// An accepted checkpoint from this file, used as the "previous" state for the
/// chain-rule cases.
struct Accepted {
    hash: String,
    payload: CheckpointPayload,
}

fn check_checkpoints(
    doc: &Value,
    file: &str,
    keys: &KeyManifest,
) -> Result<SetOutcome, RunnerError> {
    let all = cases(doc, file)?;
    let mut out = SetOutcome::new(file);

    // Pass 1: every accepted checkpoint, by hash and by size.
    let mut accepted: Vec<Accepted> = Vec::new();
    for case in &all {
        let expect = match case.get("expect") {
            Some(e) => e,
            None => continue,
        };
        if expect.get("result").and_then(Value::as_str) != Some("ACCEPT") {
            continue;
        }
        if let (Ok(bytes), Ok(hash)) = (
            need_bytes_b64(expect, "canonical_b64"),
            need_str(expect, "checkpoint_hash"),
        ) {
            if let Ok(text) = std::str::from_utf8(&bytes) {
                if let Ok(payload) = CheckpointPayload::from_canonical(text) {
                    accepted.push(Accepted { hash, payload });
                }
            }
        }
    }

    for case in &all {
        let id = case_id(case);
        out.record(&id, run_checkpoint(case, keys, &accepted));
    }
    Ok(out)
}

fn run_checkpoint(case: &Value, keys: &KeyManifest, accepted: &[Accepted]) -> Outcome {
    let expect = expect_block(case)?;
    let input = need_obj(case, "input")?;
    let result = need_str(expect, "result").unwrap_or_else(|_| "ACCEPT".to_owned());

    // The canonical bytes live under expect for accepted cases and under input
    // for rejected ones, because a rejected checkpoint is still well formed.
    let bytes = need_bytes_b64(expect, "canonical_b64")
        .or_else(|_| need_bytes_b64(input, "canonical_b64"))?;
    let text = std::str::from_utf8(&bytes).map_err(|e| format!("not UTF-8: {e}"))?;
    let payload =
        CheckpointPayload::from_canonical(text).map_err(|e| format!("payload rejected: {e}"))?;

    // The hash, where the vector states one, must match and must not depend on
    // the signature.
    if let Ok(want_hash) = need_str(expect, "checkpoint_hash") {
        let got = payload.checkpoint_hash_hex().map_err(|e| e.to_string())?;
        if got != want_hash {
            return Err(format!(
                "checkpoint_hash mismatch: want {want_hash}, got {got}"
            ));
        }
    }

    if result == "ACCEPT" {
        let signature = need_str(expect, "signature")?;
        let entry = keys
            .require(&payload.key_id, Role::Signer)
            .map_err(|e| format!("key {}: {e}", payload.key_id))?;
        let verifying = entry.verifying_key().map_err(|e| e.to_string())?;
        payload
            .verify(&signature, &verifying)
            .map_err(|e| format!("signature did not verify: {e}"))?;
        // An identical payload signed again keeps the same hash.
        if let Ok(same_as) = need_str(expect, "same_hash_as") {
            let got = payload.checkpoint_hash_hex().map_err(|e| e.to_string())?;
            if got != same_as {
                return Err("re-signing changed the checkpoint hash".to_owned());
            }
        }
        return Ok(());
    }

    let want_reason = need_str(expect, "reason")?;
    match want_reason.as_str() {
        "BAD_SIGNATURE" => {
            let signature = need_str(input, "signature")?;
            let entry = keys
                .require(&payload.key_id, Role::Signer)
                .map_err(|e| format!("key {}: {e}", payload.key_id))?;
            let verifying = entry.verifying_key().map_err(|e| e.to_string())?;
            if payload.verify(&signature, &verifying).is_ok() {
                return Err("signature verified, expected BAD_SIGNATURE".to_owned());
            }
            Ok(())
        }
        "WRONG_KEY_ROLE" => {
            // The signature is valid, but under a key whose role is not signer.
            let signed_by = need_str(input, "signed_by_key_id")?;
            let entry = keys
                .get(&signed_by)
                .ok_or_else(|| format!("unknown key {signed_by}"))?;
            let verifying = entry.verifying_key().map_err(|e| e.to_string())?;
            let signature = need_str(input, "signature")?;
            payload
                .verify(&signature, &verifying)
                .map_err(|e| format!("signature did not verify under the stated key: {e}"))?;
            match keys.require(&signed_by, Role::Signer) {
                Ok(_) => Err("key was accepted as a signer, expected WRONG_KEY_ROLE".to_owned()),
                Err(err) if err.as_str() == "WRONG_KEY_ROLE" => Ok(()),
                Err(err) => Err(format!(
                    "rejected as {}, expected WRONG_KEY_ROLE",
                    err.as_str()
                )),
            }
        }
        "BAD_GENESIS" => {
            if input
                .get("signer_has_state")
                .map(|v| v == &Value::Bool(false))
                != Some(true)
            {
                return Err("vector must state signer_has_state=false".to_owned());
            }
            match check_extends(None, &payload) {
                Ok(()) => Err("accepted as genesis, expected BAD_GENESIS".to_owned()),
                Err(err) if err.as_str() == "BAD_GENESIS" => Ok(()),
                Err(err) => Err(format!(
                    "rejected as {}, expected BAD_GENESIS",
                    err.as_str()
                )),
            }
        }
        reason @ ("NOT_EXTENDING" | "SIZE_REGRESSION" | "FORK_DETECTED") => {
            let previous = find_previous(input, accepted, reason)?;
            match check_extends(Some((&previous.payload, &previous.hash)), &payload) {
                Ok(()) => Err(format!("accepted, expected {reason}")),
                Err(err) if err.as_str() == reason => Ok(()),
                Err(err) => Err(format!("rejected as {}, expected {reason}", err.as_str())),
            }
        }
        other => Err(format!("runner does not know how to check reason {other}")),
    }
}

fn find_previous<'a>(
    input: &Value,
    accepted: &'a [Accepted],
    reason: &str,
) -> Result<&'a Accepted, String> {
    match reason {
        "NOT_EXTENDING" => {
            let hash = need_str(input, "signer_last_checkpoint_hash")?;
            accepted
                .iter()
                .find(|a| a.hash == hash)
                .ok_or_else(|| format!("no accepted checkpoint with hash {hash}"))
        }
        "SIZE_REGRESSION" => {
            let size = need_int(input, "signer_last_tree_size")?;
            accepted
                .iter()
                .find(|a| a.payload.tree_size == size)
                .ok_or_else(|| format!("no accepted checkpoint with tree_size {size}"))
        }
        "FORK_DETECTED" => {
            let hash = need_str(input, "conflicts_with_checkpoint_hash")?;
            accepted
                .iter()
                .find(|a| a.hash == hash)
                .ok_or_else(|| format!("no accepted checkpoint with hash {hash}"))
        }
        other => Err(format!("no previous-state rule for {other}")),
    }
}

fn check_global(doc: &Value, file: &str, keys: &KeyManifest) -> Result<SetOutcome, RunnerError> {
    let all = cases(doc, file)?;
    let mut out = SetOutcome::new(file);

    // Pass 1: the run-root records, in global position order.
    let mut leaves: Vec<Vec<u8>> = Vec::new();
    for case in &all {
        let Some(expect) = case.get("expect") else {
            continue;
        };
        if expect.get("record_canonical_b64").is_none() {
            continue;
        }
        match need_bytes_b64(expect, "record_canonical_b64") {
            Ok(canonical) => leaves.push(tagged_bytes(tags::RUNROOT, &canonical)),
            Err(message) => out.failures.push(format!("{}: {message}", case_id(case))),
        }
    }

    for case in &all {
        let id = case_id(&case.clone());
        out.record(&id, run_global(case, keys, &leaves));
    }
    Ok(out)
}

fn run_global(case: &Value, keys: &KeyManifest, leaves: &[Vec<u8>]) -> Outcome {
    let expect = expect_block(case)?;
    let input = need_obj(case, "input")?;

    // A run-root record: the leaf must be the tagged record.
    if expect.get("record_canonical_b64").is_some() {
        let canonical = need_bytes_b64(expect, "record_canonical_b64")?;
        let want = need_str(expect, "leaf_hash")?;
        let leaf = tagged_bytes(tags::RUNROOT, &canonical);
        if hex_lower(&merkle::leaf_hash(&leaf)) != want {
            return Err("leaf hash mismatch".to_owned());
        }
        // The record must itself be canonical and carry exactly the six fields.
        let text = std::str::from_utf8(&canonical).map_err(|e| e.to_string())?;
        if !abb_jcs::is_canonical(text) {
            return Err("record bytes are not canonical".to_owned());
        }
        let record = abb_jcs::parse(text).map_err(|e| e.to_string())?;
        let fields = record
            .as_object()
            .ok_or_else(|| "record is not an object".to_owned())?;
        let mut names: Vec<&str> = fields.iter().map(|(k, _)| k.as_str()).collect();
        names.sort_unstable();
        if names
            != vec![
                "checkpoint_hash",
                "finalized_at",
                "manifest_head",
                "root_hash",
                "run_id",
                "tree_size",
            ]
        {
            return Err(format!("unexpected record fields: {names:?}"));
        }
        return Ok(());
    }

    // A global root after n finalised runs.
    if let (Ok(size), Ok(want)) = (need_int(input, "tree_size"), need_str(expect, "root_hash")) {
        if expect.get("result").and_then(Value::as_str) == Some("ACCEPT") {
            // Handled below as a global checkpoint.
        } else {
            let n = usize::try_from(size).map_err(|_| "tree_size out of range".to_owned())?;
            let prefix = leaves
                .get(..n)
                .ok_or_else(|| "not enough records".to_owned())?;
            let got = hex_lower(&merkle::mth(prefix));
            if got != want {
                return Err(format!("global root mismatch: want {want}, got {got}"));
            }
            if hex_lower(&merkle::Frontier::from_leaf_data(prefix).root()) != want {
                return Err("frontier disagrees with the recursive root".to_owned());
            }
            return Ok(());
        }
    }

    // The signed global checkpoint.
    if expect.get("result").and_then(Value::as_str) == Some("ACCEPT") {
        let bytes = need_bytes_b64(expect, "canonical_b64")?;
        let text = std::str::from_utf8(&bytes).map_err(|e| e.to_string())?;
        let payload = CheckpointPayload::from_canonical(text).map_err(|e| e.to_string())?;
        if payload.stream_id != "global" {
            return Err("global checkpoint must use stream_id \"global\"".to_owned());
        }
        if payload.manifest_size != 0 || payload.manifest_head != ZERO_HASH_HEX {
            return Err("global checkpoint must have an empty manifest".to_owned());
        }
        let n = usize::try_from(payload.tree_size).map_err(|_| "tree_size".to_owned())?;
        let prefix = leaves
            .get(..n)
            .ok_or_else(|| "not enough records".to_owned())?;
        if payload.root_hash != hex_lower(&merkle::mth(prefix)) {
            return Err("global checkpoint root does not cover the run roots".to_owned());
        }
        let got_hash = payload.checkpoint_hash_hex().map_err(|e| e.to_string())?;
        if got_hash != need_str(expect, "checkpoint_hash")? {
            return Err("checkpoint_hash mismatch".to_owned());
        }
        let entry = keys
            .require(&payload.key_id, Role::Signer)
            .map_err(|e| e.to_string())?;
        payload
            .verify(
                &need_str(expect, "signature")?,
                &entry.verifying_key().map_err(|e| e.to_string())?,
            )
            .map_err(|e| format!("signature did not verify: {e}"))?;
        return Ok(());
    }

    // The rejection cases.
    let reason = need_str(expect, "reason")?;
    match reason.as_str() {
        "GLOBAL_ROOT_MISMATCH" => {
            let anchored = need_str(input, "anchored_root_hash")?;
            let recomputed = if let Ok(positions) = input
                .get("remaining_positions")
                .and_then(Value::as_array)
                .ok_or_else(|| "no remaining_positions".to_owned())
            {
                // A deleted run: rebuild from the positions that are left.
                let mut kept: Vec<Vec<u8>> = Vec::new();
                for item in positions {
                    let index = usize::try_from(
                        item.as_int()
                            .ok_or_else(|| "position is not an integer".to_owned())?,
                    )
                    .map_err(|_| "position out of range".to_owned())?;
                    kept.push(
                        leaves
                            .get(index)
                            .ok_or_else(|| "position past records".to_owned())?
                            .clone(),
                    );
                }
                if let Ok(want_size) = need_int(expect, "recomputed_tree_size") {
                    if kept.len() as i64 != want_size {
                        return Err("recomputed tree size mismatch".to_owned());
                    }
                }
                hex_lower(&merkle::mth(&kept))
            } else {
                // An altered run root in place.
                let position = usize::try_from(need_int(input, "position")?)
                    .map_err(|_| "position out of range".to_owned())?;
                let altered = need_bytes_b64(input, "altered_record_canonical_b64")?;
                let mut changed = leaves.to_vec();
                *changed
                    .get_mut(position)
                    .ok_or_else(|| "position past records".to_owned())? =
                    tagged_bytes(tags::RUNROOT, &altered);
                hex_lower(&merkle::mth(&changed))
            };
            let want = need_str(expect, "recomputed_root_hash")?;
            if recomputed != want {
                return Err(format!(
                    "recomputed root mismatch: want {want}, got {recomputed}"
                ));
            }
            if recomputed == anchored {
                return Err("tampering did not change the global root".to_owned());
            }
            Ok(())
        }
        "NOT_IN_SIGNER_STATE_LOG" => {
            let canonical = need_bytes_b64(input, "record_canonical_b64")?;
            let text = std::str::from_utf8(&canonical).map_err(|e| e.to_string())?;
            let record = abb_jcs::parse(text).map_err(|e| e.to_string())?;
            let claimed = record
                .get("checkpoint_hash")
                .and_then(Value::as_str)
                .ok_or_else(|| "record has no checkpoint_hash".to_owned())?;
            let known = input
                .get("signer_state_log_checkpoint_hashes")
                .and_then(Value::as_array)
                .ok_or_else(|| "no signer state log in the vector".to_owned())?;
            if known.iter().any(|h| h.as_str() == Some(claimed)) {
                return Err("the injected root is in the signer state log after all".to_owned());
            }
            Ok(())
        }
        other => Err(format!("runner does not know how to check reason {other}")),
    }
}

// --------------------------------------------------------------------------- //
// approvals, mandates, commitments (Step 9)
// --------------------------------------------------------------------------- //

/// Compare what the core decided with what the vector says.
fn expect_reject(expect: &Value, got_reason: &str) -> Outcome {
    let want_result = need_str(expect, "result")?;
    if want_result != "REJECT" {
        return Err(format!(
            "the core rejected ({got_reason}) but the vector expects {want_result}"
        ));
    }
    let want = need_str(expect, "reason")?;
    if want == got_reason {
        Ok(())
    } else {
        Err(format!("wrong reason: want {want}, got {got_reason}"))
    }
}

/// The text of the signed document: either given raw, or the canonical form of
/// the structured value (what an honest producer would have signed).
fn document_text(input: &Value, raw_field: &str, structured_field: &str) -> Result<String, String> {
    if let Some(text) = input.get(raw_field).and_then(Value::as_str) {
        return Ok(text.to_owned());
    }
    let value = need_obj(input, structured_field)?;
    abb_jcs::to_canonical(value).map_err(|e| format!("cannot canonicalize the vector input: {e}"))
}

fn digest_hex(bytes: &[u8]) -> String {
    use sha2::Digest as _;
    hex_lower(&sha2::Sha256::digest(bytes))
}

fn check_approvals_set(
    doc: &Value,
    file: &str,
    keys: &KeyManifest,
) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        out.record(&id, run_approval(&case, keys));
    }
    Ok(out)
}

fn run_approval(case: &Value, keys: &KeyManifest) -> Outcome {
    use abb_checkpoint::ApprovalStatement;
    let input = need_obj(case, "input")?;
    let expect = expect_block(case)?;
    let text = document_text(input, "statement_text", "statement")?;

    let statement = match ApprovalStatement::from_canonical(&text) {
        Ok(s) => s,
        Err(_) => return expect_reject(expect, "VALIDATION_FAILED"),
    };
    let key_id = need_str(input, "key_id")?;
    let entry = match keys.require(&key_id, Role::Approver) {
        Ok(entry) => entry,
        Err(_) => return expect_reject(expect, "WRONG_KEY_ROLE"),
    };
    let signature = need_str(input, "signature")?;
    let verifying = entry.verifying_key().map_err(|e| e.to_string())?;
    if statement.verify(&signature, &verifying).is_err() {
        return expect_reject(expect, "BAD_SIGNATURE");
    }

    // It verified, so the vector must say ACCEPT, with the same bytes.
    if need_str(expect, "result")? != "ACCEPT" {
        return Err("the core accepted a statement the vector says to reject".to_owned());
    }
    let canonical = need_bytes_b64(expect, "canonical_b64")?;
    if canonical != text.as_bytes() {
        return Err("canonical bytes differ from the vector".to_owned());
    }
    let digest = digest_hex(&statement.signing_bytes().map_err(|e| e.to_string())?);
    let want = need_str(expect, "signing_digest")?;
    if digest != want {
        return Err(format!("signing digest: want {want}, got {digest}"));
    }
    Ok(())
}

fn check_mandates_set(
    doc: &Value,
    file: &str,
    keys: &KeyManifest,
) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        out.record(&id, run_mandate(&case, keys));
    }
    Ok(out)
}

fn run_mandate(case: &Value, keys: &KeyManifest) -> Outcome {
    use abb_checkpoint::Mandate;
    let input = need_obj(case, "input")?;
    let expect = expect_block(case)?;

    // Host-matching cases carry a pattern list and a host, no signature.
    if let Some(host) = input.get("host").and_then(Value::as_str) {
        let hosts = input
            .get("allowed_hosts")
            .and_then(Value::as_array)
            .ok_or_else(|| "missing allowed_hosts".to_owned())?;
        let mandate = Mandate {
            mandate_id: "m".to_owned(),
            issuer_key_id: "k".to_owned(),
            subject: "s".to_owned(),
            allowed_hosts: hosts
                .iter()
                .filter_map(|h| h.as_str().map(str::to_owned))
                .collect(),
            allowed_action_types: Vec::new(),
            max_actions: 0,
            max_spend_minor_units: None,
            currency: None,
            not_before: 0,
            not_after: 0,
        };
        let verdict = if mandate.allows_host(host) {
            "ALLOWED"
        } else {
            "DENIED"
        };
        let want = need_str(expect, "result")?;
        return if verdict == want {
            Ok(())
        } else {
            Err(format!("host {host:?}: want {want}, got {verdict}"))
        };
    }

    let text = document_text(input, "mandate_text", "mandate")?;
    let mandate = match Mandate::from_canonical(&text) {
        Ok(m) => m,
        Err(_) => return expect_reject(expect, "VALIDATION_FAILED"),
    };
    let key_id = need_str(input, "key_id")?;
    let entry = match keys.require(&key_id, Role::MandateIssuer) {
        Ok(entry) => entry,
        Err(_) => return expect_reject(expect, "WRONG_KEY_ROLE"),
    };
    let signature = need_str(input, "signature")?;
    let verifying = entry.verifying_key().map_err(|e| e.to_string())?;
    if mandate.verify(&signature, &verifying).is_err() {
        return expect_reject(expect, "BAD_SIGNATURE");
    }

    if need_str(expect, "result")? != "ACCEPT" {
        return Err("the core accepted a mandate the vector says to reject".to_owned());
    }
    let canonical = need_bytes_b64(expect, "canonical_b64")?;
    if canonical != text.as_bytes() {
        return Err("canonical bytes differ from the vector".to_owned());
    }
    let digest = mandate.digest_hex().map_err(|e| e.to_string())?;
    let want = need_str(expect, "mandate_digest")?;
    if digest != want {
        return Err(format!("mandate digest: want {want}, got {digest}"));
    }
    Ok(())
}

fn check_commitments_set(doc: &Value, file: &str) -> Result<SetOutcome, RunnerError> {
    let mut out = SetOutcome::new(file);
    for case in cases(doc, file)? {
        let id = case_id(&case);
        out.record(&id, run_commitment(&case));
    }
    Ok(out)
}

fn run_commitment(case: &Value) -> Outcome {
    let input = need_obj(case, "input")?;
    let expect = expect_block(case)?;
    let salt = hex_decode(&need_str(input, "salt_hex")?).map_err(|_| "salt is not hex")?;
    if salt.len() != abb_checkpoint::SALT_LEN {
        return expect_reject(expect, "BAD_SALT");
    }
    let value = abb_jcs::parse(&need_str(input, "value_json")?).map_err(|e| e.to_string())?;
    let got = abb_checkpoint::field_commitment(&salt, &value).map_err(|e| e.to_string())?;
    let want = need_str(expect, "commitment")?;
    if got != want {
        return Err(format!("commitment: want {want}, got {got}"));
    }
    if let Ok(plain) = need_str(expect, "differs_from_plain_digest") {
        if got == plain {
            return Err("the commitment equals a plain digest of the value".to_owned());
        }
    }
    Ok(())
}

// --------------------------------------------------------------------------- //
// entry point
// --------------------------------------------------------------------------- //

/// Run every frozen set in `dir` and return one outcome per file.
pub fn check_all(dir: &Path) -> Result<Vec<SetOutcome>, RunnerError> {
    let keys_doc = load(&dir.join("keys").join("test_keys.json"))?;
    let keys = KeyManifest::from_value(&keys_doc)
        .map_err(|e| RunnerError::Malformed(format!("keys/test_keys.json: {e}")))?;

    let mut outcomes = Vec::new();
    let plan: Vec<(&str, SetRunner)> = vec![
        ("jcs/canonical.json", check_jcs_canonical),
        ("jcs/invalid.json", check_jcs_invalid),
        ("hashing/domain_tags.json", check_hashing_tags),
        ("hashing/tree_hashes.json", check_hashing_tree),
        ("merkle/roots.json", check_merkle_roots),
        ("merkle/inclusion.json", check_merkle_inclusion),
        ("merkle/consistency.json", check_merkle_consistency),
        ("merkle/malformed.json", check_merkle_malformed),
    ];
    for (file, runner) in plan {
        let doc = load(&path_of(dir, file))?;
        outcomes.push(runner(&doc, file)?);
    }

    let doc = load(&path_of(dir, "checkpoint/checkpoints.json"))?;
    outcomes.push(check_checkpoints(
        &doc,
        "checkpoint/checkpoints.json",
        &keys,
    )?);

    let doc = load(&path_of(dir, "global/global_log.json"))?;
    outcomes.push(check_global(&doc, "global/global_log.json", &keys)?);

    let doc = load(&path_of(dir, "approval/approvals.json"))?;
    outcomes.push(check_approvals_set(&doc, "approval/approvals.json", &keys)?);
    let doc = load(&path_of(dir, "mandate/mandates.json"))?;
    outcomes.push(check_mandates_set(&doc, "mandate/mandates.json", &keys)?);
    let doc = load(&path_of(dir, "commitment/commitments.json"))?;
    outcomes.push(check_commitments_set(&doc, "commitment/commitments.json")?);

    Ok(outcomes)
}

fn path_of(dir: &Path, relative: &str) -> PathBuf {
    let mut path = dir.to_path_buf();
    for part in relative.split('/') {
        path.push(part);
    }
    path
}

/// Total cases passed and total failures across every set.
#[must_use]
pub fn totals(outcomes: &[SetOutcome]) -> (usize, usize) {
    let passed = outcomes.iter().map(|o| o.passed).sum();
    let failed = outcomes.iter().map(|o| o.failures.len()).sum();
    (passed, failed)
}
